#!/usr/bin/env bash
set -euo pipefail

REPO="$(cd -- "$(dirname -- "$0")" && pwd -P)"
BUILD_ROOT="${LIBREECHO_BUILD_ROOT:-/home/andy/build/libreecho/pipeline}"
PRIVATE_ROOT="${LIBREECHO_PRIVATE_ROOT:-$HOME/.config/libreecho-build/private}"

mkdir -p "$BUILD_ROOT/work" "$BUILD_ROOT/generated" "$BUILD_ROOT/out" \
  "$PRIVATE_ROOT"
chmod 0700 "$PRIVATE_ROOT"

# Compatibility projections let the reviewed status/OTA/flash tools read the
# external state while keeping generated bytes and secrets out of this repo.
for name in work generated out; do
  ln -sfn -- "$BUILD_ROOT/$name" "$REPO/$name"
done
ln -sfn -- "$PRIVATE_ROOT" "$REPO/private"

cat <<EOF
build_repository=$REPO
build_root=$BUILD_ROOT
private_root=$PRIVATE_ROOT
status=CONFIGURED
EOF
